<?php
namespace SanctuaryShop\Component\Sanctuaryshop\Administrator\View\Reports;
defined('_JEXEC') or die;
use Joomla\CMS\Factory;use Joomla\CMS\Language\Text;use Joomla\CMS\MVC\View\HtmlView as BaseHtmlView;use Joomla\CMS\Toolbar\ToolbarHelper;
class HtmlView extends BaseHtmlView {public $summary,$statuses,$providers,$products,$from,$to,$status;public function display($tpl=null):void{$input=Factory::getApplication()->getInput();$from=$input->getString('from');$to=$input->getString('to');$this->from=preg_match('/^\d{4}-\d{2}-\d{2}$/',$from)?$from:date('Y-m-01');$this->to=preg_match('/^\d{4}-\d{2}-\d{2}$/',$to)?$to:date('Y-m-d');$this->status=(string) $input->getString('status', '');$m=$this->getModel();$this->summary=$m->summary($this->from,$this->to,$this->status);$this->statuses=$m->grouped('o.status',$this->from,$this->to);$this->providers=$m->grouped('o.payment_method',$this->from,$this->to);$this->products=$m->products($this->from,$this->to);ToolbarHelper::title(Text::_('COM_SANCTUARYSHOP_REPORTS'),'chart-bar');parent::display($tpl);}}